def retrieve_vector(query: str, k: int = 10, tenant: str | None = None) -> list[dict]:
q_vec = embed([query])[0]
pipeline = [
{
"$vectorSearch": {
"index": "chunks_vec",
"path": "embedding",
"queryVector": q_vec,
"numCandidates": 200, # search width
"limit": k,
**({"filter": {"metadata.tenant": tenant}} if tenant else {}),
}
},
{
"$project": {
"_id": 1, "text": 1, "metadata": 1,
"score": {"$meta": "vectorSearchScore"},
}
},
]
return list(db.chunks.aggregate(pipeline))
Knobs:
numCandidates: HNSW search width. Higher = better recall + slower. Start 200; raise to 500-1000 if recall is bad.
limit: top-k to return.
filter: pre-filters narrow the search space. Big wins for multi-tenant or category-scoped queries.

Vector search misses exact-keyword hits; lexical misses semantic paraphrases. Combine for best recall.
def retrieve_hybrid(query: str, k: int = 10, tenant: str | None = None) -> list[dict]:
q_vec = embed([query])[0]
pipeline = [
{
"$vectorSearch": {
"index": "chunks_vec",
"path": "embedding",
"queryVector": q_vec,
"numCandidates": 200,
"limit": 20,
**({"filter": {"metadata.tenant": tenant}} if tenant else {}),
}
},
{"$addFields": {"vec_score": {"$meta": "vectorSearchScore"}, "lex_score": 0}},
{"$unionWith": {
"coll": "chunks",
"pipeline": [
{
"$search": {
"index": "chunks_text",
"compound": {
"must": [{"text": {"query": query, "path": "text"}}],
**({"filter": [{"text": {"query": tenant, "path": "metadata.tenant"}}]} if tenant else {}),
}
}
},
{"$limit": 20},
{"$addFields": {"lex_score": {"$meta": "searchScore"}, "vec_score": 0}},
]
}},
# Reciprocal Rank Fusion
{"$group": {
"_id": "$_id",
"text": {"$first": "$text"},
"metadata": {"$first": "$metadata"},
"vec_score": {"$max": "$vec_score"},
"lex_score": {"$max": "$lex_score"},
}},
# weighted combination — tune per workload
{"$addFields": {"combined": {"$add": [
{"$multiply": ["$vec_score", 0.6]},
{"$multiply": ["$lex_score", 0.4]}
]}}},
{"$sort": {"combined": -1}},
{"$limit": k},
]
return list(db.chunks.aggregate(pipeline))
The weights (0.6 / 0.4) are workload-dependent — tune with an eval set (Chapter 8).
A better scoring approach is Reciprocal Rank Fusion (RRF) — combine ranks, not raw scores:
rrf_score = sum_over_rankings(1 / (k + rank))
Atlas + the LangChain integration provide hybrid retriever helpers that do this for you.

def answer_stream(query: str, tenant: str | None = None):
candidates = retrieve_hybrid(query, k=20, tenant=tenant)
top = rerank(query, candidates, top_n=5)
messages = assemble_prompt(query, top)
stream = oa.chat.completions.create(
model="gpt-4o",
messages=messages,
temperature=0.2,
stream=True,
)
for delta in stream:
token = delta.choices[0].delta.content
if token:
yield token
# after streaming finishes, return citations
yield {"citations": [{"i": i+1, **c["metadata"], "preview": c["text"][:200]} for i, c in enumerate(top)]}
